import pty, os, time, select
def run(args, inputs):
    pid, fd = pty.fork()
    if pid==0:
        os.execv("/workspace/executable", ["/workspace/executable"]+args)
    out=b""; idx=0; start=time.time()
    while time.time()-start<5:
        r,_,_=select.select([fd],[],[],0.5)
        if r:
            try: data=os.read(fd,4096)
            except OSError: break
            if not data: break
            out+=data
            if idx < len(inputs) and b"password" in out.lower():
                time.sleep(0.1); os.write(fd, inputs[idx].encode()+b"\r"); idx+=1; out+=b"<SENT>"
        else:
            if idx < len(inputs):
                # maybe prompt without word?
                pass
    try: os.close(fd)
    except: pass
    _,status=os.waitpid(pid,0)
    print(out.decode(errors='replace')); print("status",status)
for auth in [":p:",":p","::",":","a:",":p:q"]:
    print("AUTH",repr(auth))
    run(["--offline","-I","-a",auth,"https://example.com/x"],["secret"])
PY
