# ---------- URL parsing (WHATWG-ish) ----------
SPECIAL_SCHEMES = {"http": 80, "https": 443, "ws": 80, "wss": 443, "ftp": 21, "file": None}

class UrlError(Exception):
    pass

def _percent_encode(s, encode_set, encoding='utf-8'):
    out = []
    for ch in s:
        o = ord(ch)
        if o < 0x20 or o == 0x7f or o > 0x7e or ch in encode_set:
            for b in ch.encode('utf-8'):
                out.append('%%%02X' % b)
        else:
            out.append(ch)
    return ''.join(out)

def _idna_encode(host):
    # host already lowercased, percent-decoded parts
    if not host:
        raise UrlError("empty host")
    # Check invalid chars: space and controls and # / : ; = @ [ \ ] ^ | ? etc in host (rust url)
    # WHATWG forbidden host code points for special schemes: \0 \t \n \r space # / : < > ? @ [ \ ] ^ |
    forbidden = set('\x00\t\n\r #/:<>?@[\\]^|')
    # Percent-decoded host is handled before; we receive decoded str
    labels = host.split('.')
    out_labels = []
    for label in labels:
        if label == "":
            out_labels.append("")
            continue
        # if ascii only, keep (but check forbidden)
        if all(ord(c) < 128 for c in label):
            if any(c in forbidden for c in label):
                raise UrlError("invalid international domain name")
            out_labels.append(label)
        else:
            # Use python idna (IDNA2003) approximation; also forbidden check for ascii chars inside
            try:
                puny = label.encode('idna').decode('ascii')
            except Exception:
                raise UrlError("invalid international domain name")
            out_labels.append(puny)
    result = '.'.join(out_labels)
    return result

