def prompt_password(username, url):
    # Prompt to /dev/tty if possible; else raise No such device error
    # Format: http: password for {username}@{host}: 
    host = url.host or ""
    prompt = f"http: password for {username}@{host}: "
    try:
        # rpassword reads from tty and prints prompt to tty (or stderr?)
        tty_in = open('/dev/tty', 'rb', buffering=0)
        tty_out = open('/dev/tty', 'wb', buffering=0)
    except OSError as e:
        runtime_error(os_error_str(e))
    try:
        tty_out.write(prompt.encode())
        tty_out.flush()
        # read line with echo disabled if tty is a terminal
        import termios
        fd = tty_in.fileno()
        old = termios.tcgetattr(fd)
        new = termios.tcgetattr(fd)
        new[3] = new[3] & ~termios.ECHO
        try:
            termios.tcsetattr(fd, termios.TCSAFLUSH, new)
            line = b""
            while True:
                ch = tty_in.read(1)
                if not ch or ch == b'\n' or ch == b'\r':
                    break
                line += ch
        finally:
            termios.tcsetattr(fd, termios.TCSAFLUSH, old)
            tty_out.write(b"\n")
        return line.decode('utf-8', 'replace')
    except Exception as e:
        if isinstance(e, RuntimeExit):
            raise
        # If termios fails, fall back to line read
        try:
            line = tty_in.readline()
            return line.decode('utf-8', 'replace').rstrip('\r\n')
        except Exception as e2:
            runtime_error(os_error_str(e2) if isinstance(e2, OSError) else str(e2))

