        runtime_error(os_error_str(e))
    try:
        tty_out.write(prompt.encode())
        tty_out.flush()
        # read line with echo disabled if tty is a terminal
        import termios
        fd = tty_in.fileno()
        old = termios.tcgetattr(fd)
        new = termios.tcgetattr(fd)
        new[3] = new[3] & ~termios.ECHO
        try:
            termios.tcsetattr(fd, termios.TCSAFLUSH, new)
            line = b""
            while True:
                ch = tty_in.read(1)
                if not ch or ch == b'\n' or ch == b'\r':
                    break
                line += ch
        finally:
            termios.tcsetattr(fd, termios.TCSAFLUSH, old)
            tty_out.write(b"\n")
