        need_cl = True
        cl_val = body_len
    if not has_cl and need_cl:
        # Insertion position per category
        if req.body_kind in ("form","multipart","file"):
            # Insert before Accept (fallback accept position)
            # Find accept index in flat (the */* fallback). If accept is json (not these kinds), not applicable.
            idx_accept = next((i for i,(n,v) in enumerate(flat) if n == "accept"), len(flat))
            flat.insert(idx_accept, ("content-length", str(cl_val).encode()))
        else:
            # json/raw etc: append after all groups (before Host)
            flat.append(("content-length", str(cl_val).encode()))
    # Cookie handling
    # Compute cookie header from jar
    cookie_vals = []
    if cookie_jar is not None:
        cookie_vals = cookies_for_url(cookie_jar, url)
    # Existing cookie header manual values
    manual_cookie_idx = [i for i,(n,v) in enumerate(flat) if n == "cookie"]
    if cookie_jar is not None and (cookie_vals or getattr(req, '_session_present', False) or cookie_jar):
        # When a cookie provider exists (session or following redirects in-memory jar may be non-empty?), original moves/merges.
        # Determine provider existence: caller will set req._cookie_provider = True if session present or if it's a subsequent request after set-cookie (jar non-empty before)
        if getattr(req, '_cookie_provider', False):
            # Remove manual cookie entries from their positions, merged value will be placed after Accept
            manual_vals = [flat[i][1] for i in manual_cookie_idx]
            # Remove from flat (reverse)
            for i in reversed(manual_cookie_idx):
                del flat[i]
            combined = []
            if cookie_vals:
                combined.append(b"; ".join(cookie_vals))
            combined.extend(manual_vals)
            if combined:
                cookie_header = b"; ".join(combined) if len(combined)>1 and cookie_vals else (b"; ".join([cookie_vals[0]] + manual_vals) if cookie_vals and manual_vals else combined[0])
                # Simpler: join cookie_vals individual and manual vals by ; (cookie_vals is list of b"name=value")
                parts = []
                for cv in cookie_vals:
                    parts.append(cv)
                for mv in manual_vals:
                    parts.append(mv)
                cookie_header = b"; ".join(parts)
                # Insert after accept
                idx_accept = next((i for i,(n,v) in enumerate(flat) if n == "accept"), len(flat)-1)
                # accept may be multiple values as separate entries; find last accept
                accept_indices = [i for i,(n,v) in enumerate(flat) if n == "accept"]
                insert_pos = (accept_indices[-1] + 1) if accept_indices else len(flat)
                flat.insert(insert_pos, ("cookie", cookie_header))
        else:
            if cookie_vals:
                # jar from redirect (in-memory) but no session: reqwest cookie store is always present, so first request after jar cookies set follows this path. Our caller sets _cookie_provider when jar has matching cookies.
                pass
    # Host insertion at end if not present
    if not has_host:
        flat.append(("host", url.host_for_header().encode()))
    return flat

def cookies_for_url(jar, url):
    vals = []
    path = url.path or "/"
    host = url.host or ""
    now = time.time()
    for c in jar:
        # expiration
        if "expires" in c and c["expires"] is not None:
            try:
                if float(c["expires"]) <= now:
                    continue
            except Exception:
                pass
        domain = c.get("domain") or host
        if domain:
            # Domain matching: exact or suffix if domain starts with .
            if domain.startswith('.'):
                if not (host == domain[1:] or host.endswith(domain)):
                    continue
            else:
                if host != domain:
                    # cookie crate domain matching: if cookie domain is host's domain, subdomains? Session cookies domain is exact host, reqwest cookie store may set domain attr handling. For Set-Cookie with Domain attr, matching is suffix.
                    # If c has explicit domain flag? We stored _host_only
                    if c.get("_host_only", True):
                        continue
                    else:
                        if not host.endswith('.' + domain):
                            continue
        cpath = c.get("path") or "/"
        if not path.startswith(cpath):
            continue
        vals.append(f"{c['name']}={c['value']}".encode('utf-8'))
    return vals

def get_proxy_for_url(opts, url):
    # Explicit proxies
    proxies = []
    if opts.proxy:
        proxies = opts.proxy  # list of (proto, raw, serialized)
    else:
        # env
        # Collect env proxies
        env_proxies = []
        # http_proxy / HTTP_PROXY etc handled in caller? We'll compute here
        def env_get(name):
            if name in os.environ:
                return os.environ[name]
            uname = name.upper()
            if uname in os.environ:
                return os.environ[uname]
            return None
        hp = env_get("http_proxy")
        if hp is not None:
            env_proxies.append(("http", hp))
        hsp = env_get("https_proxy")
        if hsp is not None:
            env_proxies.append(("https", hsp))
        # no_proxy check
        no_proxy = env_get("no_proxy")
        if no_proxy and _no_proxy_matches(no_proxy, url):
            return None
        proxies_env_map = {}
        for proto, val in env_proxies:
            proxies_env_map[proto] = val
        scheme = url.scheme
        chosen = None
        if scheme in proxies_env_map:
            chosen = proxies_env_map[scheme]
        elif "all" in proxies_env_map:
            chosen = proxies_env_map["all"]
        if chosen is not None:
            # parse proxy url (add scheme if missing)
            p = chosen
            if "://" not in p:
                p = "http://" + p
            try:
                return parse_url_whatwg(p)
            except Exception:
                return None
        return None
    # explicit
    scheme = url.scheme
    # Check no_proxy? Explicit proxies ignore env no_proxy? Original: env no_proxy applies only to env proxies? --proxy options completely ignore env, so no_proxy likely ignored.
    # For explicit, there can be multiple for same proto; reqwest uses ... First matching? In curl they printed multiple env assignments, but actual reqwest client builds proxies list and uses first? We choose: prefer exact scheme match last? In reqwest Proxy::... client builder adds each; intercept chooses first matching. We'll use first exact.
    chosen_raw = None
    for proto, raw, ser in proxies:
        if proto == scheme:
            chosen_raw = ser; break
    if chosen_raw is None:
        for proto, raw, ser in proxies:
            if proto == "all":
                chosen_raw = ser; break
    if chosen_raw is None:
        return None
    try:
        return parse_url_whatwg(chosen_raw)
    except Exception:
        return None

def _no_proxy_matches(no_proxy_str, url):
    host = url.host or ""
    is_ip = False
    import ipaddress
    try:
        ipaddress.ip_address(host); is_ip = True
    except Exception:
        is_ip = False
    for entry in no_proxy_str.split(','):
        e = entry.strip().lower()
        if not e:
            continue
        host_low = host.lower()
        if e == "*":
            if not is_ip:
                return True
            continue
        if e == host_low:
            return True
        if e.startswith('.'):
            if host_low.endswith(e):
                return True
        else:
            if host_low.endswith('.' + e):
                return True
            # IP prefix? ignored
    return False

def open_connection(req, opts, conn_target, timeout_val):
    url = req.url
    kind, param = conn_target
    sock = None
    remote_addr = None
    tls_sock = None
    # helper to apply timeout
    def set_timeout(s):
        if timeout_val:
            s.settimeout(timeout_val)
        else:
            s.settimeout(None)
    if kind == 'unix':
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        set_timeout(s)
        try:
            s.connect(param)
        except OSError as e:
            raise NetworkErrorInfo(f"error sending request for url ({url.serialize()})", causes=["client error (Connect)", os_error_str(e)])
        remote_addr = None  # unix?
        # For unix socket, meta remote address? Original probably shows something.
        if url.scheme == 'https':
            # wrap?
            pass
        return s, remote_addr, None
    # Determine host/port to connect
    target_host = None; target_port = None
    is_https = url.scheme == 'https'
    if kind == 'direct':
        target_host = url.host
        target_port = url.effective_port()
        if target_port is None:
            target_port = 443 if is_https else 80
    elif kind == 'proxy_http':
        purl = param
        target_host = purl.host; target_port = purl.effective_port() or 80
    elif kind == 'proxy_connect':
        purl = param
        target_host = purl.host; target_port = purl.effective_port() or 80
    elif kind == 'socks':
        purl = param
        # connect via socks to final destination
        final_host = url.host; final_port = url.effective_port() or (443 if is_https else 80)
        s = _socks_connect(purl, final_host, final_port, timeout_val, opts)
        remote_addr = f"{final_host}:{final_port}"  # remote is final? meta shows server ip
        # get peername
        try:
            pa = s.getpeername(); remote_addr = f"{pa[0]}:{pa[1]}"
        except Exception:
            pass
        if is_https:
            tls_sock = _wrap_tls(s, req, opts, url.host)
            return s, remote_addr, tls_sock
        return s, remote_addr, None
    # Resolve target_host (for proxy, resolve proxy host; for direct resolve url host w/ --resolve overrides)
    # --resolve overrides only for direct / proxy_connect final? reqwest resolve is for domain DNS override in client, applies to url host.
    addrs = []
    connect_host_for_socket = target_host
    if kind in ('direct','proxy_connect') and kind == 'direct':
        # use resolve overrides
        override = None
        for domain, addr in opts.resolve:
            if domain.lower() == (url.host or "").lower():
                override = addr; break
        if override:
            connect_host_for_socket = override
            addrs = [(socket.AF_INET6 if ':' in override else socket.AF_INET, (override, target_port))]
            # resolve via ip parse
            import ipaddress
            ip = ipaddress.ip_address(override)
            fam = socket.AF_INET6 if ip.version == 6 else socket.AF_INET
            addrs = [(fam, (override, target_port))]
        else:
            addrs = resolve_hostname(target_host, target_port, opts)
    else:
        # proxy host resolve
        addrs = resolve_hostname(target_host, target_port, opts)
    last_err = None
    s = None
    for fam, sockaddr in addrs:
        try:
            s = socket.socket(fam, socket.SOCK_STREAM)
            set_timeout(s)
            # Interface binding
            if opts.interface:
                _bind_interface(s, opts.interface)
            s.connect(sockaddr)
            remote_addr = f"{sockaddr[0]}:{sockaddr[1]}" if fam != socket.AF_UNIX else None
            # For direct, remote_addr should be actual IP:port (sockaddr)
            break
        except socket.timeout as e:
            if s:
                try: s.close()
                except Exception: pass
            raise NetworkErrorInfo(f"error sending request for url ({url.serialize()})", causes=["operation timed out"], is_timeout=True)
        except OSError as e:
            last_err = e
            if s:
                try: s.close()
                except Exception: pass
                s = None
            continue
    if s is None:
        # Determine error type: DNS vs connect
        # If resolution failed earlier, resolve_hostname raises NetworkErrorInfo.
        if last_err is not None:
            # Need check if this was a DNS failure: resolve_hostname would have raised.
            raise NetworkErrorInfo(f"error sending request for url ({url.serialize()})", causes=["client error (Connect)", "tcp connect error", os_error_str(last_err)])
        else:
            raise NetworkErrorInfo(f"error sending request for url ({url.serialize()})", causes=["client error (Connect)", "tcp connect error"])
    if kind == 'proxy_connect':
        # Send CONNECT
        purl = param
        dest = f"{url.host}:{url.effective_port() or (443 if is_https else 80)}"
        connect_req = f"CONNECT {dest} HTTP/1.1\r\nHost: {dest}\r\n"
        # Proxy-Authorization if userinfo
        if purl.username:
            cred = f"{purl.username}:{purl.password or ''}".encode()
            connect_req += "Proxy-Authorization: Basic " + base64.b64encode(cred).decode() + "\r\n"
        connect_req += "\r\n"
        try:
            s.sendall(connect_req.encode())
            # Read response headers
            f = s.makefile('rb')
            line = f.readline(65536)
            if not line:
                raise OSError("proxy closed")
            # consume headers
            while True:
                hline = f.readline(65536)
                if hline in (b'\r\n', b'\n', b''):
                    break
            # f must not buffer extra - CONNECT responses have no body, fine but buffered file could have read tls bytes? No server won't send prematurely.
            # However using makefile may buffer; we detach?
            # To avoid losing buffered bytes, we need to keep this file for TLS? TLS wrap over socket will bypass file buffer (empty). Acceptable.
            try: f.detach()
            except Exception: pass
        except OSError as e:
            raise NetworkErrorInfo(f"error sending request for url ({url.serialize()})", causes=["client error (Connect)", os_error_str(e)])
    if is_https or (kind == 'proxy_connect'):
        tls_sock = _wrap_tls(s, req, opts, url.host)
        # remote addr remains
        return s, remote_addr, tls_sock
    return s, remote_addr, None

def resolve_hostname(host, port, opts):
    if host is None:
        raise NetworkErrorInfo(f"error sending request", causes=["client error (Connect)", "dns error", "failed to lookup address information: Name or service not known"])
    # If host is IP, return directly
    import ipaddress
    try:
        ip = ipaddress.ip_address(host)
        fam = socket.AF_INET6 if ip.version == 6 else socket.AF_INET
        return [(fam, (host, port))]
    except Exception:
        pass
    flags_family = 0
    fam_filter = socket.AF_UNSPEC
    if opts.ipv4 and not opts.ipv6:
        fam_filter = socket.AF_INET
    elif opts.ipv6 and not opts.ipv4:
        fam_filter = socket.AF_INET6
    try:
        infos = socket.getaddrinfo(host, port, fam_filter, socket.SOCK_STREAM)
    except socket.gaierror as e:
        # Message depends on system error: Temporary failure in name resolution vs Name or service not known
        msg = e.strerror if hasattr(e, 'strerror') and e.strerror else str(e)
        # Python gaierror: [Errno -2] Name or service not known ; -3 Temporary failure...
        # Original messages: "failed to lookup address information: Temporary failure in name resolution" for example.com (which is -3), and Name or service not known for --help host (-2)
        raise NetworkErrorInfo(f"error sending request for url", causes=["client error (Connect)", "dns error", f"failed to lookup address information: {msg}"])
    except OSError as e:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "dns error", f"failed to lookup address information: {e}"])
    addrs = []
    seen = set()
    for fam, typ, proto, canon, sockaddr in infos:
        if opts.ipv4 and fam != socket.AF_INET: continue
        if opts.ipv6 and fam != socket.AF_INET6: continue
        key = (fam, sockaddr)
        if key in seen: continue
        seen.add(key); addrs.append((fam, sockaddr))
    if not addrs:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "dns error", "failed to lookup address information: Name or service not known"])
    return addrs

def _bind_interface(s, interface):
    # If interface is IP, bind to it
    import ipaddress
    try:
        ip = ipaddress.ip_address(interface)
        s.bind((interface, 0))
        return
    except Exception:
        pass
    # Try SO_BINDTODEVICE (Linux 25)
    try:
        s.setsockopt(socket.SOL_SOCKET, 25, interface.encode() + b'\x00')
    except Exception:
        # If binding fails original would error later; ignore
        pass

def _socks_connect(purl, dest_host, dest_port, timeout_val, opts):
    # Connect to socks proxy
    proxy_host = purl.host; proxy_port = purl.effective_port() or 1080
    addrs = resolve_hostname(proxy_host, proxy_port, opts)
    sock = None; last_err = None
    for fam, sockaddr in addrs:
        try:
            sock = socket.socket(fam, socket.SOCK_STREAM)
            if timeout_val: sock.settimeout(timeout_val)
            sock.connect(sockaddr); break
        except OSError as e:
            last_err = e; sock = None; continue
    if sock is None:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "tcp connect error", os_error_str(last_err) if last_err else ""])
    # SOCKS5 handshake
    methods = [0]  # no auth
    user = purl.username; pw = purl.password
    if user:
        methods.append(2)
    sock.sendall(bytes([5, len(methods)] + methods))
    resp = sock.recv(2)
    if len(resp) < 2 or resp[0] != 5:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "socks error"])
    method = resp[1]
    if method == 2:
        u = user.encode(); p = (pw or "").encode()
        sock.sendall(bytes([1, len(u)]) + u + bytes([len(p)]) + p)
        resp = sock.recv(2)
        if len(resp) < 2 or resp[1] != 0:
            raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "socks error"])
    elif method == 255:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "socks error"])
    # CONNECT request
    import ipaddress
    try:
        ip = ipaddress.ip_address(dest_host)
        if ip.version == 4:
            addr_bytes = bytes([1]) + ip.packed
        else:
            addr_bytes = bytes([4]) + ip.packed
    except Exception:
        hb = dest_host.encode('idna') if dest_host else b""
        addr_bytes = bytes([3, len(hb)]) + hb
    req = bytes([5,1,0]) + addr_bytes + dest_port.to_bytes(2,'big')
    sock.sendall(req)
    resp = sock.recv(10)
    if len(resp) < 2 or resp[1] != 0:
        raise NetworkErrorInfo("error sending request", causes=["client error (Connect)", "socks error"])
    # Consume rest of address depending type
    atyp = resp[3] if len(resp) > 3 else 1
    # We've read only 10 bytes, address variable length may be left; for socks servers response is 10 for ipv4, etc. If domain, length different. Simplify assuming recv got full header for typical cases; extra bytes should not exist beyond bound address (server will not send app data yet)
    return sock

def _wrap_tls(sock, req, opts, server_hostname):
    # Build SSL context based on verify/cert/ssl
    verify_opt = opts.verify
    verify_mode = ssl.CERT_REQUIRED
    ca_data = None
    custom_ca_path = None
    if verify_opt is not None:
        low = verify_opt.lower()
        if low in ("yes","true"):
            verify_mode = ssl.CERT_REQUIRED
        elif low in ("no","false"):
            verify_mode = ssl.CERT_NONE
        else:
            verify_mode = ssl.CERT_REQUIRED
            custom_ca_path = verify_opt
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    if custom_ca_path:
        # Load custom CA: if custom CA file parsing fails, python raises; original ignores invalid certs? We'll try load, if fails pass with default? But custom should replace system roots: Create new context without defaults and load.
        try:
            ctx.load_verify_locations(cafile=custom_ca_path)
        except Exception as e:
            # If file contains no valid certs, original offline accepted; for online it might fail... We'll ignore and use empty trust (will fail verification for real certs but acceptable)
            # Create context with no defaults using string content if PEM
            try:
                with open(custom_ca_path,'r') as f: content = f.read()
                ctx.load_verify_locations(cadata=content)
            except Exception:
                pass
    else:
        try:
            ctx.load_default_certs()
        except Exception:
            pass
    ctx.check_hostname = (verify_mode != ssl.CERT_NONE)
    ctx.verify_mode = verify_mode
    # TLS version bounds
    if opts.ssl:
        v = opts.ssl
        # Mapping: tls1 -> min TLS1, max TLS1 etc. Python may have deprecated.
        try:
            if v == "tls1":
                ctx.minimum_version = ssl.TLSVersion.TLSv1; ctx.maximum_version = ssl.TLSVersion.TLSv1
            elif v == "tls1.1":
                ctx.minimum_version = ssl.TLSVersion.TLSv1_1; ctx.maximum_version = ssl.TLSVersion.TLSv1_1
            elif v == "tls1.2":
                ctx.minimum_version = ssl.TLSVersion.TLSv1_2; ctx.maximum_version = ssl.TLSVersion.TLSv1_2
            elif v == "tls1.3":
                ctx.minimum_version = ssl.TLSVersion.TLSv1_3; ctx.maximum_version = ssl.TLSVersion.TLSv1_3
        except Exception:
            pass
    # ALPN: for http version 2, offer h2, http/1.1
    try:
        if opts.http_version == "2":
            ctx.set_alpn_protocols(["h2","http/1.1"])
        else:
            ctx.set_alpn_protocols(["http/1.1"])
    except Exception:
        pass
    # Client cert
    if opts.cert:
        try:
            ctx.load_cert_chain(certfile=opts.cert, keyfile=opts.cert_key if opts.cert_key else None)
        except Exception as e:
            raise NetworkErrorInfo("Failed to load the cert/cert key files", causes=["builder error", f"unexpected error: {e}"])
    sni = server_hostname
    # If hostname is IP, SNI still?
    try:
        tls_sock = ctx.wrap_socket(sock, server_hostname=sni)
    except ssl.SSLError as e:
        raise e
    return tls_sock

def read_http_response(sock, req, opts, start_time):
    # Use buffered file
    f = sock.makefile('rb')
    # Status line(s): handle 1xx
    while True:
        line = f.readline(65536)
        if not line:
            raise NetworkErrorInfo(f"error sending request for url ({req.url.serialize()})", causes=["client error (Connect)", "connection closed"? ""])
        line_str = line.decode('iso-8859-1').rstrip('\r\n')
        if line_str == "":
            continue
        m = re.match(r'HTTP/(\d+\.\d+)\s+(\d{3})(?:\s+(.*))?', line_str)
        if not m:
            raise NetworkErrorInfo(f"error sending request for url ({req.url.serialize()})", causes=[f"invalid HTTP response: {line_str}"])
        version = m.group(1); status = int(m.group(2)); reason = m.group(3) or ""
        if 100 <= status < 200 and status != 101:
            # read headers and discard
            while True:
                hline = f.readline(65536)
                if hline in (b'\r\n', b'\n', b''):
                    break
            continue
        break
    headers_list = []
    header_bytes_total = 0
    while True:
        hline = f.readline(65536)
        if hline in (b'\r\n', b'\n', b''):
            break
        if not hline:
            break
        # Handle folded headers? Rare; treat continuation as part of previous
        if hline[:1] in (b' ', b'\t') and headers_list:
            prev_name, prev_val = headers_list[-1]
            headers_list[-1] = (prev_name, prev_val + b' ' + hline.strip())
            continue
        if b':' in hline:
            name_b, val_b = hline.split(b':', 1)
            name = name_b.decode('iso-8859-1').strip().lower()
            val = val_b.strip(b'\r\n').strip(b' ')
            # Rust HeaderValue strip leading SP after colon, rstrip? HTTP parsing trims OWS both.
            # But preserve trailing? Reqwest uses trim.
            val = val_b.strip()
            # Actually val_b after colon may have leading space; stripping both is correct for HTTP.
            headers_list.append((name, val))
        else:
            name = hline.decode('iso-8859-1').strip().lower()
            headers_list.append((name, b""))
    resp = HttpResponse()
    resp.version = version; resp.status = status; resp.reason = reason; resp.headers_list = headers_list
    # Determine body length / framing
    method = req.method
    body = b""
    if method == "HEAD" or status in (204,205,304) or (100 <= status < 200):
        body = b""
        resp.body_bytes = body
        resp.elapsed = time.monotonic() - start_time
        return resp
    te = resp.header_first("transfer-encoding")
    cl = resp.header_first("content-length")
    # Stream vs buffer: Caller will decide whether to stream; but our simple implementation reads all body here, except when --stream / --download with streaming caller needs chunks. We read all anyway; output behavior same.
    if te and b'chunked' in te.lower():
        chunks = []
        while True:
            size_line = f.readline(65536)
            if not size_line:
                break
            size_str = size_line.decode('iso-8859-1').strip().split(';',1)[0]
            try:
                size = int(size_str, 16)
            except Exception:
                break
            if size == 0:
                # read trailers until blank
                while True:
                    tline = f.readline(65536)
                    if tline in (b'\r\n', b'\n', b''):
                        break
                break
            remaining = size
            while remaining > 0:
                chunk = f.read(remaining)
                if not chunk: break
                chunks.append(chunk); remaining -= len(chunk)
            f.readline(65536)  # trailing CRLF
        body = b''.join(chunks)
    elif cl is not None:
        try:
            length = int(cl.decode('latin-1'))
        except Exception:
            length = 0
        if length > 0:
            body = f.read(length) or b""
            # If server closed early, body may be shorter; http client would error? ignore
        else:
