def generate_download_filename(resp, url):
    # Content-Disposition
    cd = resp.header_first("content-disposition")
    filename = None
    if cd:
        cd_str = cd.decode('utf-8','replace')
        m = re.search(r'filename\*\s*=\s*(?:[^;\']+\'\')?"?([^";]+)"?', cd_str)
        if m:
            filename = urllib.parse.unquote(m.group(1))
        else:
            m = re.search(r'filename\s*=\s*"?([^";]+)"?', cd_str)
            if m:
                filename = m.group(1)
    if not filename:
        path = url.path or "/"
        seg = path.rstrip('/').rsplit('/',1)[-1] if path.rstrip('/') else ""
        if seg:
            filename = seg
        else:
            filename = "index"
        # If filename has no extension, add based on content-type
        if '.' not in filename:
            ct = resp.header_first("content-type")
            ct_str = ct.decode('latin-1') if ct else ""
            mime_to_ext = {"application/octet-stream":"bin","text/plain":"txt","application/json":"json","text/html":"html","application/pdf":"pdf","image/png":"png","image/jpeg":"jpg","text/css":"css","application/xml":"xml","text/xml":"xml"}
            ext = mime_to_ext.get(ct_str.split(';')[0].strip(), "bin" if filename=="index" else "")
            if ext:
                filename = f"{filename}.{ext}" if filename != "index" or True else filename
            elif filename == "index":
                filename = "index.bin"
    filename = os.path.basename(filename)
    if not filename:
        filename = "index.bin"
    # Dedupe
    orig = filename
    counter = 1
    while os.path.exists(filename):
        filename = f"{orig}-{counter}"
        counter += 1
    return filename

