        # Normal online execution
        # Destination and printers
        if opts.download:
            return execute_download(req, opts, session, jar, url)
        else:
            # Non-download output
            dest = sys.stdout.buffer
            out_file_handle = None
            dest_is_file = False
            if opts.output:
                try:
                    out_file_handle = open(opts.output, 'wb')
                except OSError as e:
                    runtime_error(os_error_str(e))
