def persist_session_from_request(session, req, opts, items):
    if session.read_only:
        return
    # Auth
    if req.raw_auth_for_session is not None:
        session.auth_type = req.auth_type_for_session
        session.raw_auth = req.raw_auth_for_session
    # Headers (from req.session_set_groups)
    # Build new headers list: start from existing session.headers (names lower)
    existing = [(n.lower(), v) for n, v in session.headers]
    # set groups from request (after unsets? original persistence excludes unset effect but includes explicit sets)
    # req.session_set_groups contains session+explicit groups after we removed unset groups in build. That would lose session headers if they were unset? But original retained them. Our build removed unset groups from set_groups_order globally, affecting persistence incorrectly. To compensate, we have req.session_unset; if a session header was unset, we should retain it in persistence.
    # For now, start from existing, then apply set groups (excluding content-type/len/cookie)
    groups = getattr(req, 'session_set_groups', [])
    for name, vals in groups:
        lname = name.lower()
        if lname in ("content-type","content-length"):
            continue
        if lname == "cookie":
            # handled as cookies below
            continue
        for v in vals:
            # replace existing
            found=False
            for idx,(en,ev) in enumerate(existing):
                if en==lname:
                    existing[idx]=(lname,v); found=True; break
            if not found:
                existing.append((lname,v))
    # If a session header was unset, it was removed from groups: ensure it remains in existing (it already does) - fine.
    session.headers = existing
    # Cookies from manual Cookie header? This is handled in caller via jar: session.cookies will be set from jar before saving in execute functions
    # For offline, no response cookies, but manual cookies from header set groups should become cookies
    for name, vals in groups:
        if name.lower() == "cookie":
            for v in vals:
                for part in v.split(';'):
                    part=part.strip()
                    if '=' in part:
                        cn, cv = part.split('=',1)
                        cookie={"name":cn.strip(),"value":cv.strip(),"path":"/","domain":req.url.host or ""}
                        # replace
                        session.cookies = [c for c in session.cookies if not (c['name']==cookie['name'] and c.get('domain')==cookie['domain'] and c.get('path')==cookie['path'])]
                        session.cookies.append(cookie)
    # Also sync jar cookies into session if offline? jar is in req._cookie_jar
    # In execute functions they will set session.cookies = jar cleaned

def execute_normal(req, opts, session, jar, printer, dest_is_tty):
    print_str = determine_print(opts, offline=False)
    if print_str is None:
        # default
        print_str = "hb" if dest_is_tty else "b"
    history_str = opts.history_print if opts.history_print is not None else print_str
    show_history = opts.all or opts.verbose>0
    # Download preprocessing already set check_status
    if opts.check_status is not None:
        effective_check = opts.check_status
    else:
        effective_check = not getattr(opts, 'httpie_compat_mode', False)
    current_req = req
    first = True
    redirect_seen = 0
    digest_retried = False
    final_resp = None
    exit_code = 0
    # For session cookie sync
    while True:
        # Print request for first or history requests
        if first:
            if any(c in print_str for c in "HB"):
                printer.print_request(current_req, set(c for c in "HB" if c in print_str))
        else:
            if show_history and any(c in history_str for c in "HB"):
                printer.print_request(current_req, set(c for c in "HB" if c in history_str))
        # Execute
        try:
            # set cookie provider based on jar for this request: if jar non-empty after first etc
            if not first and jar:
                current_req._cookie_provider = True
            resp = do_http_request(current_req, opts, jar)
        except NetworkErrorInfo as e:
            # Format error
            # Timeout has special formatting
            if e.is_timeout:
                msg = f"{BIN_NAME}: error: error sending request for url ({current_req.url.serialize()})\n\nCaused by:\n    operation timed out\n"
                err_text(msg)
                return 2
            else:
                # Build message
                url_str = current_req.url.serialize()
                if e.msg.startswith("error sending request"):
                    base = f"{BIN_NAME}: error: error sending request for url ({url_str})\n"
                    if e.causes:
                        if len(e.causes)==1:
                            base += f"\nCaused by:\n    {e.causes[0]}\n"
                        else:
                            base += "\nCaused by:\n" + "\n".join(f"    {i}: {c}" for i,c in enumerate(e.causes)) + "\n"
                    err_text(base)
                else:
                    # Other errors (cert load etc)
                    err_text(f"{BIN_NAME}: error: {e.msg}\n")
                return 1
        # Update cookies
        update_cookies_from_response(jar, resp, current_req.url)
        # Digest retry?
        is_digest_challenge = (resp.status == 401 and getattr(current_req, 'is_digest', False) and not digest_retried)
        if is_digest_challenge:
            digest_header = digest_auth_header(current_req, resp, opts)
            if digest_header:
                digest_retried = True
                if show_history:
                    # print intermediate response using history_str (h,b,m)
                    printer.print_response(resp, set(c for c in "hbm" if c in history_str), meta_info=(resp.elapsed, resp.remote_addr))
                import copy
                next_req = copy.deepcopy(current_req)
                next_req.headers.append_value("authorization", digest_header)
                # If there's already authorization group (url etc) append will merge
                current_req = next_req
                first = False
                continue
        # Redirect handling
        is_redirect = resp.status in (301,302,303,307,308) and resp.header_first("location") is not None
        if is_redirect and opts.follow:
            redirect_seen += 1
            effective_max = opts.max_redirects if opts.max_redirects is not None else 10
            if effective_max != 0 and redirect_seen >= effective_max:
                # Save session? Original on too many redirects - session? Probably not? But exit 6 before session save?
                err_text(f"{BIN_NAME}: error: Too many redirects (--max-redirects={effective_max})\n")
                return 6
            if show_history:
                # print intermediate response: if history includes b, original added a separator newline after intermediary body? Our print_response for body will handle? For history responses, they terminate body with an extra newline if b is present?
                # We'll print via printer and if 'b' in history components and resp is not final, add newline handling in print_response_history wrapper
                print_history_response(printer, resp, history_str)
            next_req = build_next_request(current_req, resp, opts)
            if next_req is None:
                final_resp = resp; break
            current_req = next_req
            first = False
            continue
        final_resp = resp
        break
    # Print final response
    if final_resp is not None:
        # Meta info
        printer.print_response(final_resp, set(c for c in "hbm" if c in print_str), meta_info=(final_resp.elapsed, final_resp.remote_addr))
        # Check status
        code = status_exit_code(final_resp.status, opts.follow)
        if effective_check and code != 0:
            exit_code = code
            if opts.quiet < 2 and not dest_is_tty:
                err_text(f"{BIN_NAME}: warning: HTTP {final_resp.status} {final_resp.reason}\n")
        else:
            exit_code = 0
        # Session persistence
        if session is not None:
            persist_session_from_request(session, req, opts, [])
            # Sync jar to session cookies (clean internal keys)
            cleaned=[]
            for c in jar:
                co={"name":c["name"],"value":c["value"]}
                if "expires" in c: co["expires"]=c["expires"]
                if "path" in c: co["path"]=c["path"]
                if "domain" in c: co["domain"]=c["domain"]
                cleaned.append(co)
            session.cookies = cleaned
            try:
                save_session(session, final_resp.url or req.url)
            except RuntimeExit as e:
                err_text(e.text); return e.code
    return exit_code

def print_history_response(printer, resp, history_str):
    comps = set(c for c in "hbm" if c in history_str)
    if not comps:
        return
    # Original: after intermediary response body, there is a separating newline (printed as part of ...?). Observed: hb history gave headers + "\n" + "\n" after? It gave 302 headers then blank line then \n then final. If comps include 'b', they printed empty body plus newline. Our print_response prints headers (ends \n\n) and body (empty writes nothing). Need extra newline if 'b' in comps.
    printer.print_response(resp, comps, meta_info=(resp.elapsed, resp.remote_addr))
    if 'b' in comps:
        # Only if body printing happened: add one newline separator (but for textual bodies, final body printed would have been raw - they add \n between exchanges)
        # Check observed: -v redirect case with history hb - body of 302 was empty -> there were 2 blank lines after headers before next request: headers end \n\n + extra \n = our addition.
        # For non-empty intermediate body, they'd add \n after body too.
        printer.write(b"\n")

